#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Build searchable/filterable product hub with ItemList schema."""
from pathlib import Path
from html import escape
import re, json, html

BASE='https://pishtaj.ir/'
OUT=Path('services/products')

def clean(x): return re.sub(r'\s+',' ',re.sub(r'<[^>]+>',' ',x or '')).strip()
def tag(s,t):
    m=re.search(rf'<{t}[^>]*>(.*?)</{t}>',s,re.I|re.S); return clean(m.group(1)) if m else ''
def desc(s):
    m=re.search(r'<meta\s+[^>]*name=["\']description["\'][^>]*content=["\']([^"\']*)',s,re.I|re.S)
    return html.unescape(m.group(1)).strip() if m else ''
def cat(s):
    m=re.search(r'<span class="ptf-chip">([^<]+)</span>',s,re.I)
    return html.unescape(m.group(1)).strip() if m else 'محصولات صنعتی'

syn={
'ball-valve':'بال ولو شیر توپی ball valve api 6d','gate-valve':'گیت ولو gate valve api 600','globe-valve':'گلوب ولو globe valve api 623','check-valve':'چک ولو check valve dual plate','butterfly-valve':'باترفلای ولو butterfly api 609','control-valve':'کنترل ولو control valve cv kv','psv-prv-safety-valve':'psv prv safety relief شیر اطمینان','valve-actuator':'اکچویتور actuator عملگر','flowmeter':'فلومتر دبی سنج flowmeter','magnetic-flowmeter':'magmeter magnetic فلومتر مغناطیسی','coriolis-flowmeter':'coriolis کوریولیس mass flow','vortex-flowmeter':'vortex ورتکس بخار','pressure-transmitter':'ترانسمیتر فشار pressure transmitter','differential-pressure-transmitter':'dp dpt اختلاف فشار','radar-level-transmitter':'radar level رادار لول','vfd-soft-starter':'vfd soft starter درایو سافت استارتر','industrial-circuit-breakers':'acb mccb vcb circuit breaker کلید','power-transformer':'ترانسفورماتور transformer','api-610-centrifugal-pump':'api 610 pump پمپ','api-5l-pipe':'api 5l pipe psl','seamless-pipe':'مانیسمان seamless a106','welding-flanges':'فلنج flange b16.5','butt-weld-fittings':'فیتینگ elbow tee reducer','industrial-gaskets':'گسکت gasket spiral wound','screw-compressor':'کمپرسور اسکرو screw','steam-trap':'تله بخار steam trap','pressure-vessel':'مخزن تحت فشار pressure vessel'}
products=[]
for f in sorted(OUT.glob('*.html')):
    if f.name=='index.html': continue
    s=f.read_text(encoding='utf-8',errors='ignore')
    title=tag(s,'h1') or tag(s,'title')
    d=desc(s); c=cat(s); slug=f.stem
    kw=' '.join([title,d,c,slug.replace('-',' '),syn.get(slug,'')]).lower()
    products.append({'title':title,'desc':d,'cat':c,'file':f.name,'slug':slug,'kw':kw})
cats=[]
for p in products:
    if p['cat'] not in cats: cats.append(p['cat'])
itemlist={'@context':'https://schema.org','@graph':[{'@type':'CollectionPage','name':'هاب محصولات صنعتی قابل تامین','url':BASE+'services/products/','inLanguage':'fa-IR'},{'@type':'ItemList','name':'فهرست محصولات صنعتی قابل تامین','itemListElement':[{'@type':'ListItem','position':i+1,'name':p['title'],'url':BASE+'services/products/'+p['file']} for i,p in enumerate(products)]}]}
buttons=''.join('<button type="button" data-filter="%s">%s</button>'%(escape(c),escape(c)) for c in cats)
cards=''.join('''<article class="ptf-card" data-category="%s" data-keywords="%s"><a href="%s" class="ptf-card-main"><b>%s</b><span>%s</span><small>%s</small></a><div class="ptf-card-actions"><a href="%s">راهنمای محصول</a><a href="../../rfq/?product=%s">ثبت RFQ</a></div></article>'''%(escape(p['cat']),escape(p['kw']),p['file'],escape(p['title']),escape(p['cat']),escape(p['desc'][:180]),p['file'],p['slug']) for p in products)
css="""body{background:#f8fafc}.ptf-hub{padding:130px 0 70px}.ptf-hero{background:linear-gradient(135deg,rgba(15,39,68,.92),rgba(17,24,39,.88)),url('../../assets/images/real/real-hero-energy-plant.jpg') center/cover;color:#fff;border-radius:32px;padding:46px}.ptf-hero h1{color:#fff;font-size:clamp(28px,4vw,42px);margin:0 0 10px}.ptf-hero p{max-width:850px;line-height:2;color:rgba(255,255,255,.86)}.ptf-search-panel{background:#fff;border:1px solid #e2e8f0;border-radius:28px;padding:22px;margin:22px 0;box-shadow:0 16px 42px rgba(15,23,42,.06)}.ptf-search-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:center}.ptf-search-row input{width:100%;box-sizing:border-box;border:2px solid #e2e8f0;border-radius:18px;padding:14px 16px;font:inherit;font-weight:800;color:#0f2744;background:#f8fafc}.ptf-count{font-weight:900;color:#ef4b1a;white-space:nowrap}.ptf-filters{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}.ptf-filters button{border:1px solid #e2e8f0;background:#fff;border-radius:999px;padding:9px 13px;font-weight:900;color:#334155;cursor:pointer}.ptf-filters button.active,.ptf-filters button:hover{background:#ef4b1a;color:#fff;border-color:#ef4b1a}.ptf-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(265px,1fr));gap:16px;margin-top:22px}.ptf-card{display:grid;gap:10px;background:#fff;border:1px solid #e2e8f0;border-radius:22px;padding:18px;box-shadow:0 14px 35px rgba(15,23,42,.06)}.ptf-card-main{display:grid;gap:8px;text-decoration:none;color:#0f2744}.ptf-card span{color:#ef4b1a;font-weight:900;font-size:13px}.ptf-card small{color:#64748b;line-height:1.8}.ptf-card-actions{display:flex;gap:8px;flex-wrap:wrap}.ptf-card-actions a{text-decoration:none;border-radius:999px;padding:8px 12px;font-size:12.5px;font-weight:900;background:#f1f5f9;color:#0f2744}.ptf-card-actions a:last-child{background:#0f2744;color:#fff}.ptf-empty{display:none;background:#fff7ed;border:1px solid #fed7aa;border-radius:18px;padding:18px;color:#9a3412;font-weight:900;margin-top:16px}@media(max-width:700px){.ptf-search-row{grid-template-columns:1fr}}"""
js="""(function(){var input=document.getElementById('productSearch'),cards=[].slice.call(document.querySelectorAll('.ptf-card')),buttons=[].slice.call(document.querySelectorAll('.ptf-filters button')),count=document.getElementById('productCount'),empty=document.getElementById('productEmpty'),active='all';function norm(s){return String(s||'').toLowerCase().replace(/ي/g,'ی').replace(/ك/g,'ک').replace(/\s+/g,' ').trim()}function apply(){var q=norm(input&&input.value),shown=0;cards.forEach(function(c){var cat=c.getAttribute('data-category')||'',kw=norm(c.getAttribute('data-keywords')||c.textContent),ok=(active==='all'||cat===active)&&(!q||kw.indexOf(q)>-1);c.style.display=ok?'grid':'none';if(ok)shown++});if(count)count.textContent=shown;if(empty)empty.style.display=shown?'none':'block'}buttons.forEach(function(b){b.addEventListener('click',function(){buttons.forEach(function(x){x.classList.remove('active')});b.classList.add('active');active=b.getAttribute('data-filter')||'all';apply()})});if(input)input.addEventListener('input',apply);apply()})();"""
